import re
from urllib.parse import urlparse

import streamlit as st
from openai import OpenAI

client = OpenAI()

ALLOWED_URL_HOSTS = {"cdn.example.com", "docs.example.com"}
_URL_IN_MARKDOWN = re.compile(r"\((https?://[^)\s]+)\)")


def is_url_allowed(url: str) -> bool:
    """The single chokepoint: no model-authored URL leaves without passing here."""
    host = urlparse(url).netloc.rstrip(".").lower()
    return host in ALLOWED_URL_HOSTS


def strip_disallowed_urls(markdown: str) -> str:
    return _URL_IN_MARKDOWN.sub(
        lambda m: "(about:blank)" if not is_url_allowed(m.group(1)) else m.group(0),
        markdown,
    )


def summarise(question: str, page_text: str) -> None:
    reply = client.chat.completions.create(
        model="gpt-4o",
        messages=[{"role": "user", "content": question + page_text}],
    )
    answer = reply.choices[0].message.content
    st.markdown(strip_disallowed_urls(answer), unsafe_allow_html=False)
